{"file_text": "@page "/settings"
@using sv_a4f7dca013094355a37656fd6e026c68.Models
@using sv_a4f7dca013094355a37656fd6e026c68.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Value.Icon</span>
                    <span class="nav-label">@section.Value.Label</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast @_toastType">
                <span>@_toastMessage</span>
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @switch (ActiveSection)
        {
            case "profile":
                @RenderProfileSection()
                break;
            case "notifications":
                @RenderNotificationsSection()
                break;
            case "security":
                @RenderSecuritySection()
                break;
            case "appearance":
                @RenderAppearanceSection()
                break;
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "profile";

    private readonly Dictionary<string, (string Label, string Icon)> _sections = new()
    {
        ["profile"] = ("Profile", "👤"),
        ["notifications"] = ("Notifications", "🔔"),
        ["security"] = ("Security", "🔒"),
        ["appearance"] = ("Appearance", "🎨")
    };

    // Toast
    private string? _toastMessage;
    private string _toastType = "success";
    private CancellationTokenSource? _toastCts;

    // Profile state
    private UserProfile? _savedProfile;
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";

    // Notifications state
    private NotificationPrefs? _savedNotificationPrefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelMuteState> _channels = new();

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _revokeSessionId;
    private bool _showRevokeConfirmation;

    // Appearance state
    private AppearanceSettings? _savedAppearance;
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private bool _isLoading = true;

    private record ChannelMuteState(string Name, bool IsMuted);

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _isLoading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        _savedProfile = await profileTask;
        ApplyProfile(_savedProfile);

        _savedNotificationPrefs = await notifTask;
        ApplyNotificationPrefs(_savedNotificationPrefs);

        _securitySettings = await securityTask;

        _savedAppearance = await appearanceTask;
        ApplyAppearance(_savedAppearance);
    }

    private void ApplyProfile(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    private void ApplyNotificationPrefs(NotificationPrefs prefs)
    {
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _channels = prefs.MutedChannels.Select(c => new ChannelMuteState(c, true)).ToList();
    }

    private void ApplyAppearance(AppearanceSettings settings)
    {
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
    }

    // Toast helpers
    private async Task ShowToast(string message, string type = "success")
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        _toastMessage = message;
        _toastType = type;
        StateHasChanged();

        try
        {
            await Task.Delay(4000, _toastCts.Token);
            DismissToast();
        }
        catch (TaskCanceledException) { }
    }

    private void DismissToast()
    {
        _toastMessage = null;
        StateHasChanged();
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
    }

    // Notifications actions
    private async Task SaveNotificationPrefs()
    {
        var mutedChannels = _channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _savedNotificationPrefs = prefs;
        await ShowToast("Notification preferences saved!");
    }

    private void ToggleChannelMute(int index)
    {
        var ch = _channels[index];
        _channels[index] = ch with { IsMuted = !ch.IsMuted };
    }

    // Security actions
    private async Task ChangePassword()
    {
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("Passwords do not match.", "error");
            return;
        }

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("All password fields are required.", "error");
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        await ShowToast("Password updated successfully!");
    }

    private void RequestRevokeSession(string sessionId)
    {
        _revokeSessionId = sessionId;
        _showRevokeConfirmation = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_revokeSessionId is not null)
        {
            await SettingsService.RevokeSessionAsync(_revokeSessionId);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            _showRevokeConfirmation = false;
            _revokeSessionId = null;
            await ShowToast("Session revoked.");
        }
    }

    private void CancelRevoke()
    {
        _showRevokeConfirmation = false;
        _revokeSessionId = null;
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _savedAppearance = settings;
        await ShowToast("Appearance settings saved!");
    }

    // Render methods
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile</h2>

            <div class="avatar-preview">
                @if (!string.IsNullOrWhiteSpace(_profileAvatarUrl))
                {
                    <img src="@_profileAvatarUrl" alt="Avatar" class="avatar-image" />
                }
                else
                {
                    <div class="avatar-placeholder">No Avatar</div>
                }
                <p class="avatar-url-display">@_profileAvatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_profileDisplayName" class="form-control" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_profileEmail" class="form-control" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="_profileBio" class="form-control" rows="4"></textarea>
            </div>

            <div class="form-group">
                <label for="avatarUrl">Avatar URL</label>
                <input id="avatarUrl" type="url" @bind="_profileAvatarUrl" class="form-control" />
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>

            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <input type="checkbox" @bind="_emailNotifications" class="toggle-switch" />
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <input type="checkbox" @bind="_pushNotifications" class="toggle-switch" />
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <input type="checkbox" @bind="_weeklyDigest" class="toggle-switch" />
                </label>
            </div>

            <h3>Muted Channels</h3>
            @if (_channels.Count == 0)
            {
                <p class="text-muted">No channels configured.</p>
            }
            else
            {
                <ul class="channel-list">
                    @for (var i = 0; i < _channels.Count; i++)
                    {
                        var index = i;
                        <li>
                            <label class="channel-item">
                                <input type="checkbox" checked="@_channels[index].IsMuted" @onchange="() => ToggleChannelMute(index)" />
                                <span>@_channels[index].Name</span>
                            </label>
                        </li>
                    }
                </ul>
            }

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
            </div>
        </section>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>

            <!-- Change Password -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(_changePasswordExpanded ? "▾" : "▸")</span>
                </button>

                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" @bind="_currentPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" @bind="_newPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" @bind="_confirmPassword" class="form-control" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Two-Factor Authentication</span>
                    <span class="status-indicator @(_securitySettings?.TwoFactorEnabled == true ? "enabled" : "disabled")">
                        @(_securitySettings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")
                    </span>
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange is not null)
            {
                <p class="text-muted">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <!-- Active Sessions -->
            <h3>Active Sessions</h3>
            @if (_securitySettings?.Sessions is { Count: > 0 })
            {
                <div class="table-container">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session != _securitySettings.Sessions.First())
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => RequestRevokeSession(session.Id)">Revoke</button>
                                        }
                                        else
                                        {
                                            <span class="text-muted">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
            else
            {
                <p class="text-muted">No active sessions.</p>
            }

            <!-- Revoke Confirmation Dialog -->
            @if (_showRevokeConfirmation)
            {
                <div class="modal-overlay">
                    <div class="modal-dialog">
                        <h4>Confirm Session Revocation</h4>
                        <p>Are you sure you want to revoke this session? The user will be logged out on that device.</p>
                        <div class="button-group">
                            <button class="btn btn-danger" @onclick="ConfirmRevokeSession">Revoke</button>
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <!-- Theme -->
            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@theme" checked="@(_theme == theme)" @onchange="() => _theme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Font Size -->
            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@size" checked="@(_fontSize == size)" @onchange="() => _fontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Language -->
            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_language" class="form-control">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Chinese">Chinese</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Compact Mode</span>
                    <input type="checkbox" @bind="_compactMode" class="toggle-switch" />
                </label>
            </div>

            <!-- Live Preview -->
            <div class="preview-area @(_theme.ToLower()) @(_fontSize.ToLower()) @(_compactMode ? "compact" : "")">
                <h4>Preview</h4>
                <p>This is how your content will look with the selected settings.</p>
                <p><strong>Theme:</strong> @_theme | <strong>Font Size:</strong> @_fontSize | <strong>Language:</strong> @_language | <strong>Compact:</strong> @(_compactMode ? "Yes" : "No")</p>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };
}
